function countPairs(nums) {
  // Does one swap inside x (or none) turn it into y?
  const reaches = (x, y) => {
    if (x === y) return true;
    const text = String(x);
    for (let a = 0; a < text.length; a++) {
      for (let b = a + 1; b < text.length; b++) {
        const chars = text.split('');
        const temp = chars[a];
        chars[a] = chars[b];
        chars[b] = temp;
        if (Number(chars.join('')) === y) return true;
      }
    }
    return false;
  };
  let total = 0;
  for (let i = 0; i < nums.length; i++) {
    for (let j = i + 1; j < nums.length; j++) {
      if (reaches(nums[i], nums[j]) || reaches(nums[j], nums[i])) total++;
    }
  }
  return total;
}

