function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(90, 100) : int(2, 8);
  const longest = large ? 6 : int(1, 4);
  // A small digit alphabet makes near-misses and rearrangements of each other likely.
  const alphabet = large ? '0123456789'.slice(0, int(3, 10)) : '0123'.slice(0, int(2, 4));
  const fresh = () => {
    const length = int(1, longest);
    let text = alphabet[int(1, alphabet.length - 1)];
    while (text.length < length) text += alphabet[int(0, alphabet.length - 1)];
    return Number(text);
  };
  const nums = [];
  while (nums.length < n) {
    if (nums.length && rand() < 0.6) {
      // Rearrange an earlier value: maybe put zeros in front, then make zero to two swaps.
      const digits = String(nums[int(0, nums.length - 1)]).padStart(int(1, longest), '0').split('');
      const swaps = int(0, 2);
      for (let s = 0; s < swaps; s++) {
        const a = int(0, digits.length - 1), b = int(0, digits.length - 1);
        [digits[a], digits[b]] = [digits[b], digits[a]];
      }
      nums.push(Number(digits.join('')));
    } else {
      nums.push(fresh());
    }
  }
  if (rand() < 0.2) nums[int(0, n - 1)] = large ? 1000000 : 1;
  return [nums];
}
